    const airBrakeRegenBlockActive = now < (Number(state.airBrake?.regenBlockedUntil) || 0);
    state.airBrake = this.createAcAirBrakeState(state.lastMoveDirection || AC_MOVEMENT_CONFIG.defaultLastMoveDirection);
